#!/usr/bin/env python3
"""Independent exact QQ identity checker. No Singular or its output basis needed."""
from __future__ import annotations
import argparse
import hashlib
import json
from pathlib import Path
import time


def verify(certificate, expected_model):
    import sympy as sp
    # The trusted model is translation.json generated by Python BEFORE Singular.
    # Never accept a certificate that changes equations, guards, or its target.
    for key in ('variables', 'variable_mapping', 'target_variable', 'equations',
                'saturation_factors', 'polynomial', 'order', 'certificate_extension',
                'saturation_encoding', 'inverse_variables'):
        if certificate.get(key) != expected_model.get(key):
            return {'verified': False, 'reason': 'MODEL_MISMATCH:' + key}
    names = certificate['variables']
    symbols = sp.symbols(' '.join(names), seq=True)
    local = dict(zip(names, symbols))
    def parse(s):
        expr = sp.sympify(s.replace('^', '**'), locals=local)
        return sp.Poly(expr, *symbols, domain=sp.QQ)
    F = [parse(e) for e in expected_model['equations']]
    y = parse('yy')
    p, one = parse(expected_model['polynomial']), parse('1')
    if expected_model.get('saturation_encoding') == 'factorwise_inverses':
        inverses = expected_model['inverse_variables']
        factors = expected_model['saturation_factors']
        if len(inverses) != len(factors):
            return {'verified': False, 'reason': 'INVERSE_COUNT_MISMATCH'}
        F.extend(one - parse(z)*parse(f) for z, f in zip(inverses, factors))
    elif expected_model.get('saturation_encoding') is None:
        # Legacy v1 evidence remains independently checkable.
        h = one
        for factor in expected_model['saturation_factors']:
            h *= parse(factor)
        F.append(one - parse('zz')*h)
    else:
        return {'verified': False, 'reason': 'UNKNOWN_SATURATION_ENCODING'}
    method = certificate['method']
    if method == 'power':
        m = certificate.get('exponent')
        if not isinstance(m, int) or not 1 <= m <= 4:
            return {'verified': False, 'reason': 'INVALID_EXPONENT'}
        rhs = p**m
    elif method == 'rabinowitsch':
        F.append(one - y*p)
        rhs = one
    else:
        return {'verified': False, 'reason': 'INVALID_METHOD'}
    coefficients = certificate['coefficients']
    if len(coefficients) != len(F):
        return {'verified': False, 'reason': 'COEFFICIENT_COUNT_MISMATCH'}
    residual = -rhs
    terms = 0
    for c, f in zip(coefficients, F):
        a = parse(c)
        terms += len(a.terms()) if not a.is_zero else 0
        residual += a*f  # exact expansion in sparse QQ polynomials
    return {'verified': bool(residual.is_zero), 'reason': 'QQ_IDENTITY_ZERO' if residual.is_zero else 'NONZERO_IDENTITY',
            'method': method, 'coefficient_count': len(F), 'coefficient_terms': terms,
            'residual_terms': 0 if residual.is_zero else len(residual.terms()),
            'library': 'sympy', 'version': sp.__version__,
            'semantics': 'sum A_i*f_i = p^m or 1; f_i are original equations plus inverse guards and optional Rabinowitsch equation',
            'singular_called': False}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('certificate', type=Path)
    parser.add_argument('--model', required=True, type=Path)
    args = parser.parse_args()
    started = time.monotonic()
    result = verify(json.loads(args.certificate.read_text()), json.loads(args.model.read_text()))
    result.update(wall_seconds=time.monotonic()-started,
                  certificate_sha256=hashlib.sha256(args.certificate.read_bytes()).hexdigest(),
                  model_sha256=hashlib.sha256(args.model.read_bytes()).hexdigest())
    print(json.dumps(result, indent=2))
    raise SystemExit(0 if result['verified'] else 1)


if __name__ == '__main__':
    main()
